package com.example.smartexpenseanalyzer.controller;
import jakarta.servlet.http.HttpSession; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/expenses") public class ExpenseController { private final com.example.smartexpenseanalyzer.service.ApiFacade app; public ExpenseController(com.example.smartexpenseanalyzer.service.ApiFacade app){this.app=app;} @GetMapping public List<Map<String,Object>> list(HttpSession session){return app.list(session);} @PostMapping public ResponseEntity<?> add(@RequestBody Map<String,String> body,HttpSession session){return app.add(body,session);} @PutMapping("/{id}") public ResponseEntity<?> edit(@PathVariable Long id,@RequestBody Map<String,String> body,HttpSession session){return app.edit(id,body,session);} @DeleteMapping("/{id}") public Map<String,String> delete(@PathVariable Long id,HttpSession session){return app.delete(id,session);} }
